ruct BlockTrailer;class CTidyHeapAction_AC;class CTidyHeapBlock_AC;class CTidyHeapState_AC;class CTidyHeapLogger_AC;class CTidyHeapFile_AC;template <class T> class CTidyHeapHashTable_AC;//========================================================================================// CTidyHeap_AC//========================================================================================class EXPORT_AC CTidyHeap_AC : public CTidyHeapSettings_AC{public:	//------------------------------------------------------------------------------------	// Constructor/Destructor	// Note: These are called from CreateTidyHeap and from Initialize, so don't call them	// yourself.	//------------------------------------------------------------------------------------			CTidyHeap_AC();		virtual ~CTidyHeap_AC();	virtual void ITidyHeap();	//------------------------------------------------------------------------------------	// Enumerations	//------------------------------------------------------------------------------------	enum eMarkers	{		kInvalidMarker = 	0xF0F0F0F0,		kMarker1 = 			0xF1F1F1F1,		kMarker2 = 			0xF2F2F2F2,		kMarker3 = 			0xF3F3F3F3,		kStateData = 		0xF5F5F5F5	};	enum eErrors	{		kNoErr,		kBadMarker1,		kBadMarker2,		kBadMarker3,		kNoMarkersFound,		kPtrCrossRefFailed,		kPtrNotInAppHeap	};	enum	{		kSettingsFileType = 'thpf',		kSettingsFileCreator = 'thap',		kStatFileType = 'thst'	};	//------------------------------------------------------------------------------------	// Info	//------------------------------------------------------------------------------------	static CTidyHeap_AC* Instance();	virtual CTidyHeapError_AC GetErr();		// new/delete/verify etc. can cause an error.	virtual CTidyHeapBlock_AC* GetBlock(void* inBlockPtr);		// This is how you get at your block class for whatever		// data you've allocated.			//-- these return numbers for currently allocated blocks		virtual long GetBlockCount() const;		//--  these are tallys for the lifetime of your app.		virtual long GetBlockCountTally() const;		virtual long GetSizeTally() const;		virtual long GetDebugSizeTally() const;	virtual float GetAveBlockSize() const;		//------------------------------------------------------------------------------------	// Utils 	//------------------------------------------------------------------------------------	virtual void VerifyAllBlocks(bool logBlockData = false);	static void Terminate();		// Usually this is called by the shared lib and you don't need to		// call it, but it's here if you want it. Use at your own risk. 	virtual CTidyHeapError_AC VerifyBlock(void* inPtr, bool logBlockData = false);		// this is here as a convienience, you can also call verify		// on the specific block you're dealing with by calling		// GetBlock first, then calling CTidyHeapBlock_AC::Verify.			virtual void MakeNextNewFail();			// This does what it says. ;-)			virtual void StopTrackingUnknownBlocks();		// This removes any unknown blocks from the list of currently outstanding		// blocks.			//------------------------------------------------------------------------------------	// Global Actions	//------------------------------------------------------------------------------------		//-- Actions installed here are called for every block.	// Note: Actions you install into TidyHeap are deleted by TidyHeap at Termination	// Time.		virtual void AquireNewAction( CTidyHeapAction_AC* inActionPtr);		// A New action is called after allocation immediately before		// new returns. 		virtual void RemoveNewAction( CTidyHeapAction_AC*  inActionPtr);		// Removes and does not delete.		virtual void AquireDeleteAction( CTidyHeapAction_AC*  inActionPtr);		// A Delete action is called immediately before deletion.		virtual void RemoveDeleteAction( CTidyHeapAction_AC*  inActionPtr);		// Removes and does not delete.				virtual void AquireTerminationAction( CTidyHeapAction_AC*  inActionPtr );		// A Termination action is called when TidyHeap terminates, after		// all the logging is completed, just before TidyHeap is deleted.		// A termination Action doesn't interact with any blocks.			virtual void RemoveTerminationAction( CTidyHeapAction_AC*  inActionPtr);		// Removes and does not delete.				virtual CTidyHeapActionList_AC& GetTerminationActionList();	virtual CTidyHeapActionList_AC& GetNewActionsList();	virtual CTidyHeapActionList_AC& GetDeleteActionList();		virtual void RemoveAllActions();		// removes all actions from global new and delete lists.			//------------------------------------------------------------------------------------	// Logging	//------------------------------------------------------------------------------------	virtual void Logf(const char* format, ...);		// Logf data strings go to the LogHook, whatever that may be.			virtual void Warnf(const char* format, ...);		// Warnf goes to CTidyHeap_AC::PrintDebugString, only if warnings are enabled.			virtual CTidyHeapLogger_AC *AquireLogger( CTidyHeapLogger_AC * inLogger, bool deletePrevious = true );		// Sending in nil will essentially turn off logging.			virtual CTidyHeapLogger_AC *GetLogger();			//-- Available Log hooks: 	// 1. LogFile	// 2. DebugStr (actually calls PrintDebugString)		// Use these interfaces to install them.			virtual void SetToDebugStrLogger( bool doHalt = false );		// if do halt is false, ";g" will be appended to the logf string,		// cause macsbug to immediately return and continue processing.			virtual void SetToLogFileLogger();			// Sets logfile hook.		//-- Misc Logging helpers	virtual void LogError();		// This will log the current error with a string description.			//------------------------------------------------------------------------------------	// MISC	//------------------------------------------------------------------------------------		static void* PushInfo(const char* fileName, short lineNum);			virtual void GetSessionFileLoc(short& vol, long &dirId);			virtual void HandleNilAllocation(const char* file, short line);		virtual CTidyHeapBlock_AC *CreateBlockObject();	CTidyHeapBlockList_AC& GetBlockList();		virtual void ExemptBlockFromLeakCheck(CTidyHeapBlock_AC* inBlock, bool exempt = true);	static void ExemptBlockFromLeakCheck(void* inBlock);	long GetExemptCount() const;		static void PrintDebugString(const char* inString, ...);		// maxlen of string is 254		//		On Mac OS this calls DebugStr.public:	static GlobalNewProc GlobalNew;	static GlobalDeleteProc GlobalDelete;protected:	virtual void HandleTermination();			public:	//------------------------------------------------------------------------------------	// CTempDisable	//------------------------------------------------------------------------------------	class CTempDisable	// CTidyHeap::CTempDisable temporarily turns off tidy heap tracking. It is like 	// exempting a block from leak checking, except it exempts all blocks that are 	// allocated while tidy heap is disabled. This can be useful with libraries where it	// may not be easy to get at internal data structures. Please note that most of the	// time you don't want to disable tidy heap. 	{	public:		CTempDisable()			:	fWasEnabled(CTidyHeap_AC::Instance()->IsEnabled())		{			if (fWasEnabled)				CTidyHeap_AC::Instance()->IsEnabled(false);		}			~CTempDisable()		{			if (fWasEnabled)				CTidyHeap_AC::Instance()->IsEnabled(true);		}	protected:		bool	fWasEnabled;	};private:	//------------------------------------------------------------------------------------	// private methods	//------------------------------------------------------------------------------------	void* CreateBlock(size_t size, const char* file, short line);		void RemoveBlock(void* ptr);		BlockHeader* FindHeader(char* ptr);		BlockTrailer* FindTrailer(BlockHeader* inHeader);		long VerifyState( CTidyHeapState_AC &  inState);		void DeleteActions( CTidyHeapActionList_AC& inList);		void DoAction( CTidyHeapAction_AC* inBlock, BlockHeader* inHeader);		static CTidyHeapBlock_AC* DefaultCreateBlockObject();	CTidyHeapMarker_AC GetMarker(void* inPtr, short markerNum );	void InstallPrefActions();		bool PtrInAppHeap(void* inPtr);		void PrintActionList(CTidyHeapActionList_AC& inList);			static long DoubleDeleteHashProc(void* inElement);	static void SetTempMemPref();public:	void* operator new(size_t inSize)	{	return GlobalNew(inSize); }		void operator delete(void* inBlock)	{	GlobalDelete(inBlock); }		void* operator new(size_t inSize, const char* /*inFileName*/, short /*inLine*/ ) // make it compatible with macro	{ return operator new(inSize); }	private:	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------	long 							fCount;	long 							fDeleteCount;	long 							fSizeTally;	long	 						fDebugTally;	long							fExemptCount;		CTidyHeapLogger_AC* 			fLogger;	char							fLogString[256];		char 							fFileName[32];	short 							fLineNum;		CTidyHeapHashTable_AC<void*>*	fDoubleDeleteHashTable;	CTidyHeapBlockList_AC 			fBlockList;	CTidyHeapActionList_AC 			fTerminationActions;	CTidyHeapActionList_AC 			fNewActions;	CTidyHeapActionList_AC 			fDeleteActions;	CTidyHeapError_AC 				fErr;	bool 							fNextNewFails;	bool							fEnabledOnStart;		static CTidyHeap_AC*			fgSelf;	static long						fgAddressRange; // for hash table	static long						fgBlockSize; // for hash table	//------------------------------------------------------------------------------------	// friends o' tidy heap.	//------------------------------------------------------------------------------------	friend void* operator new(size_t size, const char* fileName, short lineNum);	friend void* operator new(size_t size);	friend void operator delete(void* ptr );#if !defined(__MWERKS__) || __MWERKS__ >= 0x2100#if !(defined(__MRC__) && !FIXED_MPW_BUG)#if !(defined(__SC__) && !FIXED_MPW_BUG)	friend void* operator new[](size_t size, const char* file, short lineNum);	friend void operator delete[](void* ptr);#endif#endif#endif		friend class CTidyHeapState_AC;	friend class CTidyHeapBlock_AC;};	//----------------------------------------------------------------------------------------// CTidyHeap_AC's Inlines//----------------------------------------------------------------------------------------inline long CTidyHeap_AC::GetBlockCountTally() const 	{ return fCount; }inline long CTidyHeap_AC::GetSizeTally() const 	{ return fSizeTally; }inline long CTidyHeap_AC::GetDebugSizeTally() const 	{ return fDebugTally; }inline float CTidyHeap_AC::GetAveBlockSize() const 	{ return (fSizeTally / fCount); }inline CTidyHeapLogger_AC* CTidyHeap_AC::GetLogger() 	{ return fLogger; }inline long CTidyHeap_AC::GetExemptCount() const	{ return fExemptCount; }//--  these are optional macros.#define TH_SaveBlockInfo()	CTidyHeap_AC::PushInfo(__FILE__, __LINE__)	// This is an alternate to using the TH_new macro. If you call this immediately before	// a new, it will also save the pertinant creation info.//#define TH_new new(__FILE__, __LINE__)#define TH_new	CTidyHeap_AC::PushInfo(__FILE__, __LINE__) ? NULL : new	// Use this new in place of normal new. The benefit here is that the file name	// and line number is saved into the block of memory that you're creating. So	// if there's a problem with it, you'll know exactly where the block was created.	// Sorry about the ugly macro.	// You are required to define these in your environment.extern CTidyHeap_AC* CreateTidyHeap();#define gTidyHeap CTidyHeap_AC::Instance()	// for compatibility, will be removed sometime in the future				#else// Stub definitions for when tidy heap is disabledinline void TH_Stub() {}#define TH_new new#define TH_SaveBlockInfo() TH_Stub()#endif // qTidyHeap#endif // __CTidyHeap_AC__/*	Historical Change Record:		----- R11 -----		06/26/96	Changed nil back to NULL.		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		06/25/96	[1345531] Added missing includes for noload buids		06/10/96	Added methods to remove actions, to get action lists, 							tabbed over data members to look pretty. Deleted commented							out macro accessors.		06/05/96	Initial Implementation*/